from vlb_traj import Session
from scipy.spatial.transform import Rotation
import numpy as np, json

def clean(x):
 if isinstance(x,np.ndarray): return x.tolist()
 if isinstance(x,(np.floating,np.integer)): return x.item()
 if isinstance(x,dict): return {k:clean(v) for k,v in x.items()}
 if isinstance(x,(list,tuple)): return [clean(v) for v in x]
 return x
with Session() as s:
 st=s.state(); vase=st['entities']['vase_seen']; tcpq=st['robot']['tcp_quaternion_wxyz']
 def q(r):
  x,y,z,w=r.as_quat(); return [w,x,y,z]
 def r(a): return Rotation.from_quat([a[1],a[2],a[3],a[0]])
 tool=r(tcpq); obj=r([0.8346180688597674,0.07040114844242665,-0.5436293305723776,0.054069477269599715])
 desired=r(vase['quaternion_wxyz'])*(tool.inv()*obj).inv()
 print('orientations',json.dumps({'upright_tcp':q(desired),'down':tcpq,'identity':[1,0,0,0]}))
 for z in [1.05,1.10,1.15,1.20,1.25]:
  for label, quat in [('upright',q(desired)),('down',tcpq),('identity',[1,0,0,0])]:
   try: ans=s.ik([0.29,0.20,z],quat)
   except Exception as e: ans={'error':str(e)}
   print(label,z,json.dumps(clean(ans)))
